#!/usr/bin/env bash
# Direct Corelink-only secret rotation; plan mode is completely inert.
set -euo pipefail
umask 077
readonly ACK1='ACK-DIRECT-CORELINK-ROTATION-LIVE-20260908' ACK2='ACK-FORWARD-ONLY-RECOVERY-PAIR-LIVE-20260908'
PACKAGE_ROOT="$(cd -- "${BASH_SOURCE[0]%/*}/.." && pwd -P)"; readonly PACKAGE_ROOT
MODE=plan ATTEMPT=primary ROOT='' COMMIT='' SPAWN_VERSION='' FABRICD_VERSION='' SPAWN_APP='' FABRICD_APP='' CANARY_IMAGE='' OLD_TOKEN_FILE='' LIVE_ACK='' RECOVERY_ACK='' MOCK_WRANGLER='' CURL_BIN=curl VERIFY_BIN='' STABILITY_SECS=120
OOB_DIR="$HOME/.corelink/rotation-b2-20260908"; EVIDENCE_DIR="$OOB_DIR/evidence-direct"; FLEET_KEY_FILE="$OOB_DIR/fleet-busy-read-key"; CANARY_PAT_FILE="$OOB_DIR/corelink-canary-tenant-pat"
SPAWN_URL='https://corelink-spawn-worker.gmhelmold.workers.dev'; FABRICD_URL='https://corelink-fabricd.gmhelmold.workers.dev'
die(){ printf 'REFUSED: %s\n' "$*" >&2; exit 2; }
while [ "$#" -gt 0 ]; do case "$1" in
--mode) MODE="${2:?}";shift 2;;--attempt) ATTEMPT="${2:?}";shift 2;;--live-ack) LIVE_ACK="${2:?}";shift 2;;--recovery-ack) RECOVERY_ACK="${2:?}";shift 2;;--integration-root) ROOT="${2:?}";shift 2;;--expected-commit) COMMIT="${2:?}";shift 2;;--spawn-version) SPAWN_VERSION="${2:?}";shift 2;;--fabricd-version) FABRICD_VERSION="${2:?}";shift 2;;--spawn-app-id) SPAWN_APP="${2:?}";shift 2;;--fabricd-app-id) FABRICD_APP="${2:?}";shift 2;;--canary-image) CANARY_IMAGE="${2:?}";shift 2;;--oob-dir) OOB_DIR="${2:?}";shift 2;;--evidence-dir) EVIDENCE_DIR="${2:?}";shift 2;;--fleet-key-file) FLEET_KEY_FILE="${2:?}";shift 2;;--canary-pat-file) CANARY_PAT_FILE="${2:?}";shift 2;;--old-token-file) OLD_TOKEN_FILE="${2:?}";shift 2;;--mock-wrangler) MOCK_WRANGLER="${2:?}";shift 2;;--curl-bin) CURL_BIN="${2:?}";shift 2;;--verify-bin) VERIFY_BIN="${2:?}";shift 2;;--stability-secs) STABILITY_SECS="${2:?}";shift 2;;*) die "unknown argument $1";;esac;done
case "$MODE:$ATTEMPT" in plan:*|mock:primary|mock:recovery|live:primary|live:recovery);;*)die 'invalid mode/attempt';;esac
if [ "$MODE" = plan ]; then printf '%s\n' 'PLAN ONLY: no file is read, no command is run, no secret is generated.' 'Live path: lock, baseline, freeze, forward cutover, proof, canary, refreeze.';exit 0;fi
[ "$MODE" != live ] || { [ "$LIVE_ACK" = "$ACK1" ] && [ "$RECOVERY_ACK" = "$ACK2" ] || die 'both exact live acknowledgements required'; }
[ "$MODE" != mock ] || [ -x "$MOCK_WRANGLER" ] || die 'mock requires mock wrangler'
[ "$STABILITY_SECS" -ge 0 ] 2>/dev/null || die 'stability seconds must be a nonnegative integer'
[ -n "$VERIFY_BIN" ] || VERIFY_BIN="$PACKAGE_ROOT/bin/verify-close-attestation.mjs"
[ -x "$VERIFY_BIN" ] || die 'verifier must be executable'
OWNER_UID="$(id -u)"; readonly OWNER_UID
safe_file(){ [ -f "$1" ]&&[ ! -L "$1" ]&&[ "$(stat -f '%OLp' "$1")" = 600 ]&&[ "$(stat -f '%u' "$1")" = "$OWNER_UID" ]; };safe_dir(){ [ -d "$1" ]&&[ ! -L "$1" ]&&[ "$(stat -f '%OLp' "$1")" = 700 ]&&[ "$(stat -f '%u' "$1")" = "$OWNER_UID" ]; };sha(){ openssl dgst -sha256 -r "$1"|awk '{print $1}';};record(){ printf '%s\n' "$*">>"$EVIDENCE_DIR/events.log";}
secret_file_valid(){ local f="$1";safe_file "$f"||return 1;[ -s "$f" ]||return 1;[ "$(tr -cd '\r' <"$f"|wc -c|tr -d ' ')" = 0 ]||return 1;[ "$(tr -cd '\n' <"$f"|wc -c|tr -d ' ')" = 0 ]||return 1;LC_ALL=C grep -Eq '^[A-Za-z0-9+/=]+$' "$f"; }
run_wrangle(){ if [ "$MODE" = mock ];then "$MOCK_WRANGLER" "$@";return;fi;local t;t="$(npx --no-install wrangler auth token --json|jq -er '.token // .access_token // .')"||die 'wrangler OAuth unavailable';[[ "$t" =~ ^[A-Za-z0-9._~+/=-]{16,}$ ]]||die 'bad OAuth';CLOUDFLARE_API_TOKEN="$t" npx --no-install wrangler "$@";}
# A secret becomes curl configuration only through an inherited FD; never argv,
# a persistent file, output, evidence, or a child-process command line.
curl_secret(){ local f="$1";shift;safe_file "$f"||die 'secret must be nofollow owner-owned 0600';local s;s="$(<"$f")";[ -n "$s" ]||die 'empty secret';"$CURL_BIN" --fail --silent --show-error --config <(printf '%s\n' "header = \"authorization: Bearer $s\"") "$@";}
# Deliberately omit --fail here: 503 and 401 are the asserted successful
# protocol outcomes. curl still returns nonzero for DNS, TCP, TLS, and I/O
# failures, while --write-out captures the HTTP status without retaining a body.
curl_secret_status(){ local f="$1";shift;safe_file "$f"||die 'secret must be nofollow owner-owned 0600';local s;s="$(<"$f")";[ -n "$s" ]||die 'empty secret';"$CURL_BIN" --silent --show-error --output /dev/null --write-out '%{http_code}' --config <(printf '%s\n' "header = \"authorization: Bearer $s\"") "$@";}
curl_fleet(){ safe_file "$FLEET_KEY_FILE"||die 'fleet key must be nofollow owner-owned 0600';local s;s="$(<"$FLEET_KEY_FILE")";[ -n "$s" ]||die 'empty fleet key';"$CURL_BIN" --fail --silent --show-error --config <(printf '%s\n' "header = \"x-corelink-internal-auth: $s\"") "$SPAWN_URL/internal/v1/fleet/busy";}
assert_empty_fleet(){ local stage="$1" fleet;fleet="$(curl_fleet)"||die "fleet $stage read failed";printf '%s' "$fleet"|jq -e '(.busy|tonumber)==0 and (.unverifiable|tonumber)==0' >/dev/null||die "fleet $stage busy/unverifiable nonzero";record "fleet_${stage}=busy:0 unverifiable:0";}
SPAWN_CONFIG='' FABRICD_CONFIG='' LOCK='' LOCKED=0 REFREEZE_REQUIRED=0 FINAL_FROZEN=0
refreeze(){ run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate >/dev/null;run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 >/dev/null;record 'freeze=fabricd_then_spawn';}
cleanup(){ local rc=$?;if [ "$LOCKED" = 1 ]&&[ "$REFREEZE_REQUIRED" = 1 ]&&[ "$FINAL_FROZEN" != 1 ];then refreeze >/dev/null 2>&1||true;record 'exit_refreeze=attempted';fi;[ -z "$LOCK" ]||rmdir "$LOCK" 2>/dev/null||true;exit "$rc";};trap cleanup EXIT
[ -n "$ROOT" ]&&[ -n "$COMMIT" ]&&[ -n "$SPAWN_VERSION" ]&&[ -n "$FABRICD_VERSION" ]&&[ -n "$SPAWN_APP" ]&&[ -n "$FABRICD_APP" ]&&[ -n "$CANARY_IMAGE" ]&&[ -n "$OLD_TOKEN_FILE" ]||die 'missing pins';[[ "$COMMIT" =~ ^[a-f0-9]{40}$ && "$CANARY_IMAGE" =~ @sha256:[a-f0-9]{64}$ && "$SPAWN_APP" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ && "$FABRICD_APP" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]]||die 'malformed pin';safe_dir "$OOB_DIR";safe_file "$FLEET_KEY_FILE";safe_file "$CANARY_PAT_FILE";safe_file "$OLD_TOKEN_FILE"
SPAWN_CONFIG="$ROOT/deploy/cloudflare/wrangler.jsonc";FABRICD_CONFIG="$ROOT/deploy/cloudflare-fabricd/wrangler.jsonc"
if [ "$(git -C "$ROOT" rev-parse HEAD)" != "$COMMIT" ] || ! git -C "$ROOT" diff --quiet || ! git -C "$ROOT" diff --cached --quiet;then die 'source is not clean exact commit';fi;for p in deploy/cloudflare/wrangler.jsonc deploy/cloudflare-fabricd/wrangler.jsonc;do if ! git -C "$ROOT" ls-files --error-unmatch "$p">/dev/null || ! git -C "$ROOT" cat-file -e "$COMMIT:$p";then die 'canonical config untracked';fi;done
if [ -e "$EVIDENCE_DIR" ] || [ -L "$EVIDENCE_DIR" ];then safe_dir "$EVIDENCE_DIR"||die 'evidence directory must be nofollow owner-owned 0700';else mkdir "$EVIDENCE_DIR"||die 'cannot create evidence directory';chmod 700 "$EVIDENCE_DIR";safe_dir "$EVIDENCE_DIR"||die 'evidence directory must be nofollow owner-owned 0700';fi
:>"$EVIDENCE_DIR/events.log";chmod 600 "$EVIDENCE_DIR/events.log";safe_file "$EVIDENCE_DIR/events.log"||die 'evidence log must be owner-owned 0600';grep -Fq "$CANARY_IMAGE" "$SPAWN_CONFIG"||die 'canary image absent from canonical config'
LOCK="$OOB_DIR/.direct-rotation.lock";mkdir "$LOCK" 2>/dev/null||die 'exclusive rotation lock held';chmod 700 "$LOCK";LOCKED=1
assert_empty_fleet preflight
active_version(){ printf '%s' "$1"|jq -er 'sort_by(.created_on//"")|last|.versions[0].version_id'; }
sd="$(run_wrangle deployments list --name corelink-spawn-worker --json)";fd="$(run_wrangle deployments list --name corelink-fabricd --json)";sv="$(active_version "$sd")";fv="$(active_version "$fd")";[ "$sv" = "$SPAWN_VERSION" ]||die 'spawn version mismatch';[ "$fv" = "$FABRICD_VERSION" ]||die 'fabricd version mismatch';if [ "$STABILITY_SECS" -gt 0 ];then sleep "$STABILITY_SECS";fi;sv2="$(active_version "$(run_wrangle deployments list --name corelink-spawn-worker --json)")";fv2="$(active_version "$(run_wrangle deployments list --name corelink-fabricd --json)")";[ "$sv" = "$sv2" ]&&[ "$fv" = "$fv2" ]||die 'provider deployment changed during stability window';record "provider_stable_seconds=$STABILITY_SECS"
si="$(run_wrangle containers info "$SPAWN_APP")";fi="$(run_wrangle containers info "$FABRICD_APP")";printf '%s' "$si"|grep -Fq "$CANARY_IMAGE"||die 'provider spawn image mismatch';fimage="$(grep -Eo 'registry[^" ]+@sha256:[a-f0-9]{64}' "$FABRICD_CONFIG"|tail -1)";[ -n "$fimage" ]||die 'fabricd config image missing';printf '%s' "$fi"|jq -e --arg n corelink-fabricd-fabricdcontainer '.name==$n' >/dev/null||die 'provider fabricd application identity mismatch';printf '%s' "$fi"|jq -e --arg d "${fimage##*@}" '[..|strings|scan("sha256:[0-9a-f]{64}")]|unique==[$d]' >/dev/null||die 'provider fabricd image mismatch';record "baseline=commit:$COMMIT spawn_config:$(sha "$SPAWN_CONFIG") fabricd_config:$(sha "$FABRICD_CONFIG") spawn_version:$SPAWN_VERSION fabricd_version:$FABRICD_VERSION fabricd_app:$FABRICD_APP"
keys_before="$($CURL_BIN --fail --silent --show-error "$FABRICD_URL/v1/attestation/key")"||die 'pre-rotation attestation key read';key_id_before="$(printf '%s' "$keys_before"|jq -er 'if (.keys|type=="array" and length==1 and .[0].expires_ms==null and (.[0].key_id|type=="string" and length>0)) then .keys[0].key_id else error("invalid pre-rotation key shape") end')"||die 'invalid pre-rotation attestation key shape'
REFREEZE_REQUIRED=1
run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1>/dev/null;run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate>/dev/null;record 'freeze=spawn_then_fabricd'
mksecret(){ local d="$1" t;[ ! -e "$d" ]&&[ ! -L "$d" ]||die 'forward-only secret exists';t="$(mktemp "$OOB_DIR/.rotation.XXXXXXXX")";chmod 600 "$t";openssl rand -base64 32|tr -d '\r\n' > "$t";secret_file_valid "$t"||die 'generated secret must be nonempty, single-line, and trim-normalized';ln "$t" "$d"||die 'atomic nofollow secret commit failed';rm -f "$t";secret_file_valid "$d"||die 'secret commit validation failed';}
pseed="$OOB_DIR/primary.fabric-signing-seed.b64";ptok="$OOB_DIR/primary.spawn-token.b64";rseed="$OOB_DIR/recovery.fabric-signing-seed.b64";rtok="$OOB_DIR/recovery.spawn-token.b64";if [ "$ATTEMPT" = primary ];then mksecret "$pseed";mksecret "$ptok";mksecret "$rseed";mksecret "$rtok";seed="$pseed";tok="$ptok";else secret_file_valid "$pseed";secret_file_valid "$ptok";secret_file_valid "$rseed";secret_file_valid "$rtok";seed="$rseed";tok="$rtok";fi
secret_file_valid "$seed"||die 'selected signing secret is invalid';secret_file_valid "$tok"||die 'selected spawn token is invalid';run_wrangle secret put CLOUDFLARE_SPAWN_AUTH_TOKEN --config "$SPAWN_CONFIG"<"$tok";run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1>/dev/null;run_wrangle secret put FABRIC_SIGNING_KEY --config "$FABRICD_CONFIG"<"$seed";run_wrangle secret put CLOUDFLARE_SPAWN_AUTH_TOKEN --config "$FABRICD_CONFIG"<"$tok"
fabricd_info(){ run_wrangle containers info "$FABRICD_APP"; }
assert_fabricd_identity_digest(){ local info="$1";printf '%s' "$info"|jq -e --arg n corelink-fabricd-fabricdcontainer '.name==$n' >/dev/null||die 'fabricd application identity mismatch';printf '%s' "$info"|jq -e --arg d "${fimage##*@}" '[..|strings|scan("sha256:[0-9a-f]{64}")]|unique==[$d]' >/dev/null||die 'fabricd image digest mismatch';}
assert_fabricd_frozen(){ local v="$1" vars;vars="$(run_wrangle versions view "$v" --name corelink-fabricd --json)"||die 'fabricd freeze read failed';printf '%s' "$vars"|jq -e '[..|objects|select(.name?=="FABRIC_ADMISSION_PAUSED")|(.text? // .value? // "")]|length==1 and .[0]=="1"' >/dev/null||die 'fabricd admission freeze mismatch';}
fabricd_app_is_absent(){ local info list info_rc list_rc;set +e;info="$(fabricd_info 2>/dev/null)";info_rc=$?;list="$(run_wrangle containers list --json 2>/dev/null)";list_rc=$?;set -e;[ "$info_rc" != 0 ]&&[ "$list_rc" = 0 ]||return 1;printf '%s' "$list"|jq -e --arg id "$FABRICD_APP" '[..|objects|select(.id?==$id)]|length==0' >/dev/null;}
delete_fabricd_and_confirm_absence(){ local info attempt delete_rc;info="$(fabricd_info 2>/dev/null)"||die 'fabricd identity unavailable before delete';assert_fabricd_identity_digest "$info";for attempt in 1 2;do set +e;run_wrangle containers delete "$FABRICD_APP" >/dev/null 2>&1;delete_rc=$?;set -e;if fabricd_app_is_absent;then record "fabricd_container_absence_confirmed attempt:$attempt delete_rc:$delete_rc";return 0;fi;[ "$attempt" = 2 ]||sleep 1;done;die 'fabricd container absence not confirmed';}
resolve_fabricd_app_id(){ local list;list="$(run_wrangle containers list --json)"||die 'fabricd application list failed';printf '%s' "$list"|jq -er '[..|objects|select(.name?=="corelink-fabricd-fabricdcontainer" and (.id?|type)=="string")|.id]|unique|if length==1 then .[0] else error("exact fabricd application is absent or ambiguous") end';}
assert_fabricd_health(){ local health health_status health_body;health="$($CURL_BIN --silent --show-error --write-out $'\n%{http_code}' "$FABRICD_URL/v1/health")"||die 'fabricd health transport/TLS failure';health_status="${health##*$'\n'}";health_body="$(printf '%s' "${health%$'\n'*}"|tr -d '\r\n')";[ "$health_status" = 200 ]&&[ "$health_body" = ok ]||die 'fabricd health status/schema proof';record 'fabricd_health=200_ok_after_recreate';}
pre_recreate_version="$(active_version "$(run_wrangle deployments list --name corelink-fabricd --json)")";assert_fabricd_frozen "$pre_recreate_version";record "fabricd_pre_recreate=app:$FABRICD_APP version:$pre_recreate_version digest:${fimage##*@} frozen=1"
old_fabricd_app="$FABRICD_APP";delete_fabricd_and_confirm_absence;run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --strict --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate>/dev/null;FABRICD_APP="$(resolve_fabricd_app_id)";post_fabricd_info="$(fabricd_info)";assert_fabricd_identity_digest "$post_fabricd_info";post_fabricd_version="$(active_version "$(run_wrangle deployments list --name corelink-fabricd --json)")";assert_fabricd_frozen "$post_fabricd_version";assert_fabricd_health;record "fabricd_recreated=old_app:$old_fabricd_app app:$FABRICD_APP version:$post_fabricd_version digest:${fimage##*@} frozen=1"
keys="$($CURL_BIN --fail --silent --show-error "$FABRICD_URL/v1/attestation/key")";key_id_after="$(printf '%s' "$keys"|jq -er 'if (.keys|type=="array" and length==1 and .[0].expires_ms==null and (.[0].key_id|type=="string" and length>0)) then .keys[0].key_id else error("invalid post-rotation key shape") end')"||die 'not exact one selected key';[ "$key_id_before" != "$key_id_after" ]||die 'attestation key did not change';record "attestation_key=changed_from:${key_id_before}_to:${key_id_after}_single_active"
status="$(curl_secret_status "$tok" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST' 'data = "{}"') "$SPAWN_URL/v1/spawn")"||die 'new token probe transport/TLS failure';[ "$status" = 503 ]||die 'new token status proof';status="$(curl_secret_status "$OLD_TOKEN_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST' 'data = "{}"') "$SPAWN_URL/v1/spawn")"||die 'old token probe transport/TLS failure';[ "$status" = 401 ]||die 'old token status proof'
record 'release_transition=marked_before_first_unfreeze';run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:0>/dev/null;run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:0 --containers-rollout=immediate>/dev/null
payload="$(jq -nc --arg image "$CANARY_IMAGE" '{image_digest:$image,net_policy:"isolated",tmp_root:"/work/tmp",expiry_ms:60000}')";acquire="$(curl_secret "$CANARY_PAT_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST') --data "$payload" "$FABRICD_URL/v1/leases")"||die 'canary acquire';lease="$(printf '%s' "$acquire"|jq -er '.lease.lease_id')"||die 'missing .lease.lease_id';close="$(curl_secret "$CANARY_PAT_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST') --data '{"status":"succeeded"}' "$FABRICD_URL/v1/leases/$lease/close")"||die 'canary close';printf '%s' "$close"|jq -e --arg l "$lease" '.lease_id==$l and .released==true and .capture_incomplete==false'>/dev/null||die 'close teardown proof';printf '%s' "$close"|"$VERIFY_BIN" "$keys"||die 'fresh Corelink v1/v2 verifier';assert_empty_fleet post_canary;refreeze;FINAL_FROZEN=1;record 'outcome=complete_final_frozen'
